<script setup lang="ts">
import {computed,ref} from 'vue'
import {api,post} from '../api'
import {usePolling} from '../usePolling'
import {number,price,time} from '../format'
import {liquidation,observedDrawdown} from '../paper'
import type {PaperOverview} from '../paper'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
const data=ref<PaperOverview|null>(null);const busy=ref(false);const actionError=ref('');const selected=ref<string|null>(null)
const network=ref<{paused:boolean;settings:{economyMode:boolean}}|null>(null)
async function load(signal?:AbortSignal){const [paper,net]=await Promise.all([api<PaperOverview>('/api/paper',{signal}),api<{paused:boolean;settings:{economyMode:boolean}}>('/api/network',{signal})]);data.value=paper;network.value=net}
const {error}=usePolling(load,5000);const s=computed(()=>data.value?.state);const r=computed(()=>s.value?.rules)
const pnl=computed(()=>data.value?.completeEquity==null||!r.value?null:data.value.completeEquity-r.value.initialCash)
async function toggle(){if(!s.value||busy.value)return;busy.value=true;actionError.value='';try{await post(`/api/paper/${s.value.enabled?'pause':'resume'}`);await load()}catch(e){actionError.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
const detail=computed(()=>s.value?.recentTrades.find(t=>t.id===selected.value))
</script>
<template><PageIntro eyebrow="TODAY · PAPER ACCOUNT" title="先看账户，再看信号。" description="这里是日常入口。自动模拟、持仓风险和复盘结果放在一起。"><RouterLink class="replay-action" to="/journal">查看每日复盘 →</RouterLink></PageIntro><p v-if="network" class="radar-notice">{{network.paused?'联网预算已达上限：外部采集暂停，已有数据会失鲜。':network.settings.economyMode?'省流模式：关闭持续实时流，重点标的低频补齐，覆盖不足会标记缺失。':'完整采集模式运行中。'}} <RouterLink to="/network">查看流量与连接 →</RouterLink> · <RouterLink to="/forward">查看连续前瞻观察 →</RouterLink></p>
<p v-if="error||actionError" role="alert" class="radar-notice">{{actionError||error}}</p><template v-if="data&&s&&r">
<div class="paper-banner"><strong>仅虚拟资金 · {{r.version}}</strong><span>{{s.enabled?'模拟运行中':'新开仓已暂停'}} · 每5秒检查 · 不发送真实委托</span><button class="text-button" :disabled="busy||!r.researchValidated" @click="toggle">{{!r.researchValidated?'策略研究中，未开放自动开仓':s.enabled?'暂停模拟新仓':'恢复模拟新仓'}}</button></div>
<div class="stats"><StatCard label="账户净值 · USDT" :value="data.completeEquity==null?'待更新':number(data.completeEquity,2)" :foot="`本金 ${r.initialCash} · 可用 ${number(s.cash,2)}`"/><StatCard label="累计模拟盈亏" :value="pnl==null?'Unknown':number(pnl,2)" :foot="`已平仓 ${number(data.realizedPnl,2)} · 已计手续费 ${number(data.fees,2)}`"/><StatCard label="占用保证金 / 持仓" :value="`${number(data.marginUsed,0)} / ${s.positions.length}笔`" :foot="`最多 ${r.maximumPositions} 笔 · 每份 ${r.marginPerTrade} × ${r.leverage}倍`"/><StatCard label="已观测最大回撤" :value="`${number(observedDrawdown(s.curve),2)}%`" :foot="`已平仓 ${data.closedTrades} 笔 · 胜率 ${data.winRate==null?'样本不足':number(data.winRate,1)+'%'}`"/></div>
<section class="detail paper-next"><h2>{{s.positions.length?'今天先检查持仓风险':s.pending.length?'正在等待下一有效报价':'两套策略研究中，自动模拟开仓尚未启用'}}</h2><p>{{s.positions.length?'止损、止盈、超时和反向候选均由固定规则执行；暂停新仓不会停掉已有仓位的风险退出。':s.pending.length?'候选尚未成交；只采用信号出现之后的新报价，条件失效就取消。':'提前埋伏与涨幅榜机会将分别验证。结构止损、分批止盈和尾仓跟踪尚未完成研究验收，原型固定百分比不会启用。'}}</p><p>账户从 {{time(s.startedAt)}} 开始前瞻模拟，不回填此前的 APR 或其他历史成交。</p><div class="paper-buckets"><div v-for="n in 10" :key="n" :class="{occupied:s.positions.some(p=>p.bucket===n)}"><span>第 {{n}} 份</span><strong>{{r.marginPerTrade}} U</strong><small>{{s.positions.find(p=>p.bucket===n)?.symbol??'待用'}}</small></div></div><p>十份是保证金规划，手续费从可用余额另扣。最多同时两笔，余款不自动补亏损仓，也不自动追加保证金。</p></section>
<section class="detail"><h2>两条研究路线，各自验证</h2><RouterLink to="/template-library">查看 TRB / LAB / MYX / BTW 等历史样板 →</RouterLink><p><strong>提前埋伏：</strong>LAB、MYX、BTW 等历史案例及失败对照，研究启动前可见特征，不用未来涨幅反推买点。</p><p><strong>涨幅榜机会：</strong>区分启动、回踩延续、过热和派发；核对驱动依据，再输出可执行的模拟计划。</p><p>交易计划先列支撑失效点、压力位和尾仓退出，再决定仓位。证据不全就观察，不能用“稳定信号”作尚未验证的承诺。</p></section><div class="section-heading radar-heading"><h2>模拟持仓</h2><span>每笔名义金额约 {{r.marginPerTrade*r.leverage}} USDT</span></div><div class="market-panel table-scroll"><table><thead><tr><th>份额 / 合约</th><th>开仓价 / 标记价</th><th>数量 / 保证金</th><th>止损 / 止盈</th><th>估算强平线</th><th>数据时间</th></tr></thead><tbody><tr v-for="p in s.positions" :key="p.id"><td>第 {{p.bucket}} 份 · {{p.symbol}}<small>仅模拟多头 · {{r.leverage}}倍逐仓</small></td><td>{{price(p.entryPrice)}} / {{price(p.lastMark)}}<small>{{time(p.openedAt)}}</small></td><td>{{number(p.quantity,5)}}<small>剩余模拟保证金 {{number(p.remainingMargin,2)}} · 资金费假设 {{number(p.fundingCost,3)}}</small></td><td>{{price(p.stopPrice)}} / {{price(p.takePrice)}}</td><td>{{price(liquidation(p,r))}}<small>估算，非交易所强平价</small></td><td>{{time(p.lastQuoteTime)}}<small>行情失鲜时禁止虚假成交，盈亏保留 Unknown</small></td></tr><tr v-if="!s.positions.length"><td colspan="6" class="empty">目前没有模拟持仓。等待合格的新信号。</td></tr></tbody></table></div>
<div class="section-heading radar-heading"><h2>最近动作 · 为什么买、为什么不买</h2><RouterLink to="/research">需要时再展开研究数据 →</RouterLink></div><div class="market-panel table-scroll"><table><thead><tr><th>时间</th><th>合约</th><th>模拟动作</th><th>原因</th></tr></thead><tbody><tr v-for="(d,i) in [...s.decisions].reverse().slice(0,12)" :key="i"><td>{{time(d.time)}}</td><td>{{d.symbol}}</td><td>{{d.action}}</td><td class="decision-reason">{{d.reason}}</td></tr></tbody></table></div>
<div class="section-heading radar-heading"><h2>最近已平仓 · 全部为模拟</h2></div><div class="market-panel table-scroll"><table><thead><tr><th>合约 / 时间</th><th>买入 / 卖出参考价</th><th>净盈亏 USDT</th><th>费用 / 资金费假设</th><th>退出原因</th></tr></thead><tbody><tr v-for="t in [...s.recentTrades].reverse().slice(0,20)" :key="t.id" @click="selected=t.id"><td>{{t.symbol}} · 第{{t.bucket}}份<small>{{time(t.closedAt)}}</small></td><td>{{price(t.entryPrice)}} → {{price(t.exitPrice)}}</td><td :class="t.netPnl>=0?'positive':'negative'">{{number(t.netPnl,3)}}</td><td>{{number(t.fees,3)}} / {{number(t.fundingCost,3)}}</td><td>{{t.reason}}<small>{{t.quoteGap?'存在行情间隔，可能漏过盘中路径':'采样报价模拟'}} · {{t.version}}</small></td></tr><tr v-if="!s.recentTrades.length"><td colspan="5" class="empty">尚无已平仓结果，不伪造胜率或历史利润。</td></tr></tbody></table></div>
<section v-if="detail" class="detail"><h2>{{detail.symbol}} · 模拟记录</h2><p>开仓 {{time(detail.openedAt)}} · 平仓 {{time(detail.closedAt)}} · 数量 {{detail.quantity}} · 净盈亏 {{detail.netPnl}} USDT</p><p>规则 {{detail.version}} · {{detail.quoteGap?'报价存在间隔，不能证明盘中未曾触及强平':'仅按已观测报价执行，未模拟完整订单簿'}}</p></section>
<details class="detail"><summary>研究状态、费用与模拟限制</summary><p v-if="!r.researchValidated">当前仅开通账本与十份资金展示，未启用交易策略。最终计划须依据历史支撑、压力和波动率确定，按止损距离反算仓位；分批止盈及尾仓跟踪完成验证后再开放。旧的固定止盈止损原型不会作为生产策略启用。</p><p v-if="r.researchValidated">{{data.mode}}。每笔价格止损 {{r.stopPercent}}%、止盈 {{r.takePercent}}%、最多持有 {{r.maximumHoldHours}} 小时；反向候选也会退出。每日风险损失达到 {{r.dailyLossLimit}} USDT 或完成5笔后停止新仓。</p><p v-if="r.researchValidated">入场要求：新的 V2 上涨候选、分数至少65、完整度至少70、至少三类独立确认、1h涨幅0～8%、无明显反向候选，不追入信号后再涨超1%的报价。未知市值与链上风险会随证据保留，不能理解为安全。</p><p>每边手续费 {{r.feeRate*100}}%、滑点 {{r.slippageRate*100}}%；每8h保守计收 {{r.fundingCost8h*100}}% 名义金额的资金费假设，不是实际结算费率。维持保证金率估算 {{r.maintenanceRate*100}}%，未模拟交易所阶梯、盘口深度、精确数量步长或逐笔盘中路径。</p><p>止损按触发后下一可用报价含滑点计算，可能差于止损价。账本将逐仓返还金额下限设为0，这是模拟规则，不能保证真实交易不穿仓。程序关闭或数据缺失时不会执行成交；复开后的采样也不能重现缺失路径。每天复盘，不因一笔亏损自动调参。</p></details>
</template></template>
<style scoped>.paper-banner{display:flex;flex-wrap:wrap;gap:18px;align-items:center;padding:16px 20px;border:1px solid #325448;background:#122720;border-radius:8px;margin-bottom:22px;font-size:12px}.paper-banner button{margin-left:auto}.paper-banner span{color:#97b2a5}.paper-buckets{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin:20px 0}.paper-buckets>div{padding:13px;background:#10171e;border:1px solid #2b3741;border-radius:6px;display:grid;gap:7px}.paper-buckets .occupied{border-color:#59c89b;background:#173128}.paper-buckets span,.paper-buckets small{font-size:11px;color:#9aabbd;overflow-wrap:anywhere}.paper-buckets strong{font-size:18px}.paper-next h2{font-size:19px}@media(max-width:650px){.paper-buckets{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
